actions.script:
def vpa = terminal.upiVpa
def name = java.net.URLEncoder.encode(terminal.terminalName ?: "Store", "UTF-8")
def amt = amount.setScale(2, java.math.RoundingMode.HALF_UP).toString()
def tn = transactionNumber ? java.net.URLEncoder.encode("POS " + transactionNumber, "UTF-8") : "POS%20Payment"
upiString = "upi://pay?pa=${vpa}&pn=${name}&am=${amt}&cu=INR&tn=${tn}"
